# Databricks notebook source
# Odyssey bronze ingestion: public holidays generated by the MIT-licensed `holidays` package.

# COMMAND ----------
# MAGIC %pip install holidays --quiet

# COMMAND ----------
dbutils.library.restartPython()

# COMMAND ----------
import hashlib
import json
import uuid
from datetime import date, datetime, timezone

import holidays

dbutils.widgets.text("catalog", "odyssey_dev")
catalog = dbutils.widgets.get("catalog")

years = list(range(date.today().year - 1, date.today().year + 3))
countries = spark.table(f"{catalog}.silver.pilot_countries").select("iso2", "iso3", "country_name").collect()
batch_id = str(uuid.uuid4())
now = datetime.now(timezone.utc)
rows, logs, unsupported = [], [], []

for c in countries:
    try:
        try:
            cal = holidays.country_holidays(c.iso2, years=years, language="en_US")
        except Exception:
            cal = holidays.country_holidays(c.iso2, years=years)  # fall back to the default (local) language
    except NotImplementedError:
        unsupported.append(c.iso3)
        print(f"{c.country_name:<12} NOT SUPPORTED by holidays {holidays.__version__}")
        continue
    records = [{"date": d.isoformat(), "name": n} for d, n in sorted(cal.items())]
    body = json.dumps({"package": "holidays", "package_version": holidays.__version__, "years": years, "holidays": records},
                      ensure_ascii=False)
    rows.append(("public_holidays", c.iso3, None, body, 200, "public_holidays", now, batch_id,
                 hashlib.sha256(body.encode()).hexdigest()))
    logs.append((now, "public_holidays", batch_id, f"{c.iso3}/public_holidays", len(records),
                 f"{catalog}.bronze.holidays_raw", 0))
    print(f"{c.country_name:<12} {len(records):>3} holidays {years[0]}-{years[-1]}")

if rows:
    spark.createDataFrame(rows, "query_name STRING, country_iso3 STRING, country_qid STRING, response_json STRING, "
                                "http_status INT, _source STRING, _ingested_at TIMESTAMP, _batch_id STRING, "
                                "_payload_hash STRING").write.mode("append").saveAsTable(f"{catalog}.bronze.holidays_raw")
    spark.createDataFrame(logs, "run_at TIMESTAMP, source_id STRING, source_release STRING, area STRING, "
                                "row_count BIGINT, path STRING, duration_ms BIGINT").write.mode("append").saveAsTable(f"{catalog}.ops.extract_log")

print(f"BATCH {batch_id}: holidays {holidays.__version__}, {len(rows)} countries stored, unsupported: {unsupported or 'none'}")
